namespace QaAutomation.Core.Models;

/// <summary>A test case generated by the Tester agent. <c>Preconditions</c> is always "" (setup lives
/// in the steps). Step shape = {action, expected}.</summary>
public sealed class GeneratedTestCase
{
    public string Title { get; set; } = "";
    public string Preconditions { get; set; } = "";
    public List<TestCaseStep> Steps { get; set; } = [];
}

/// <summary>A bug generated by the Bug Writer agent. <c>ReproSteps</c> are plain strings; severity is
/// one of Critical/High/Medium/Low.</summary>
public sealed class GeneratedBug
{
    public string Title { get; set; } = "";
    public string Severity { get; set; } = "Medium";
    public string Preconditions { get; set; } = "";
    public List<string> ReproSteps { get; set; } = [];
    public string Expected { get; set; } = "";
    public string Actual { get; set; } = "";
    public string SuggestedFix { get; set; } = "";
}

/// <summary>Pass-1 per-test-case verdict from the Code Verifier. Status ∈ pass|fail|inconclusive.</summary>
public sealed class CodeVerdict
{
    public string TestCase { get; set; } = "";
    public string Status { get; set; } = "inconclusive";
    public string Evidence { get; set; } = "";
    public string Reasoning { get; set; } = "";
}

/// <summary>Pass-2 per-step verdict from the Code Verifier. Status ∈ pass|fail|inconclusive.</summary>
public sealed class StepVerdict
{
    public string Action { get; set; } = "";
    public string Expected { get; set; } = "";
    public string Status { get; set; } = "inconclusive";
    public string Actual { get; set; } = "";
}

/// <summary>A test case fed INTO the Code Verifier (from ADO-linked cases or local drafts).</summary>
public sealed class TestCaseInput
{
    public string Title { get; set; } = "";
    public string Preconditions { get; set; } = "";
    public List<TestCaseStep> Steps { get; set; } = [];
}
